/* CSS PART 3 OF 3 */

/* ==================================================
   CONTACT / CONVERSION AREA
================================================== */
.contact-section {
  padding-block: 110px;
  background: var(--color-green);
  color: var(--color-white);
}

.contact-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  gap: 85px;
  align-items: start;
}

.contact-copy .eyebrow {
  color: #e3a185;
}

.contact-copy h2 {
  color: var(--color-white);
}

.contact-copy > p {
  max-width: 450px;
  color: rgba(255, 255, 255, 0.82);
}

.contact-links {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 18px;
  margin-top: 35px;
}

.contact-links a {
  color: var(--color-white);
  font-size: 1.05rem;
  font-weight: 700;
}

.contact-links a:hover {
  color: #efb398;
}

.contact-form-wrap {
  padding: 42px;
  border-radius: var(--radius-small);
  background: var(--color-white);
  color: var(--color-ink);
  box-shadow: var(--shadow-soft);
}

.contact-form-wrap h3 {
  margin-bottom: 28px;
}

.contact-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.form-field.full-width {
  grid-column: 1 / -1;
}

.form-field label {
  color: var(--color-ink);
  font-size: 0.8rem;
  font-weight: 800;
}

.form-field input,
.form-field textarea,
.form-field select {
  width: 100%;
  min-height: 51px;
  padding: 13px 15px;
  border: 1px solid var(--color-line);
  border-radius: var(--radius-small);
  background: #fbfbf8;
  color: var(--color-ink);
  outline-offset: 3px;
}

.form-field textarea {
  min-height: 125px;
  resize: vertical;
}

.form-field input:focus,
.form-field textarea:focus,
.form-field select:focus {
  border-color: var(--color-green);
  outline: 2px solid var(--color-green);
}

.contact-form .btn {
  grid-column: 1 / -1;
  justify-self: start;
  min-width: 190px;
  border: 0;
}

.form-note {
  grid-column: 1 / -1;
  margin: 0;
  color: var(--color-ink-soft);
  font-size: 0.76rem;
}

/* ==================================================
   FOOTER
================================================== */
.site-footer {
  padding: 48px 0 25px;
  background: var(--color-ink);
  color: var(--color-white);
}

.footer-main {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 40px;
  padding-bottom: 35px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.18);
}

.footer-brand {
  max-width: 390px;
}

.footer-brand strong {
  display: block;
  margin-bottom: 9px;
  font-family: var(--font-heading);
  font-size: 1.45rem;
  font-weight: 500;
}

.footer-brand p {
  margin-bottom: 0;
  color: rgba(255, 255, 255, 0.68);
  font-size: 0.85rem;
}

.footer-nav {
  display: flex;
  flex-wrap: wrap;
  gap: 15px 28px;
}

.footer-nav a {
  color: rgba(255, 255, 255, 0.8);
  font-size: 0.82rem;
  font-weight: 700;
}

.footer-nav a:hover {
  color: #efb398;
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding-top: 22px;
  color: rgba(255, 255, 255, 0.58);
  font-size: 0.75rem;
}

/* ==================================================
   RESPONSIVE: TABLET
================================================== */
@media (max-width: 1050px) {
  :root {
    --container-gutter: 5%;
  }

  .hero {
    grid-template-columns: 1fr 0.8fr;
  }

  .hero-content {
    padding-left: 5vw;
  }

  .services-layout,
  .about-layout,
  .roof-layout,
  .contact-layout {
    gap: 45px;
  }

  .project-gallery {
    grid-template-rows: 250px 250px;
  }

  .contact-form-wrap {
    padding: 30px;
  }
}

/* ==================================================
   RESPONSIVE: MOBILE NAVIGATION & CONTENT
================================================== */
@media (max-width: 760px) {
  :root {
    --header-height: auto;
    --container-gutter: 6%;
  }

  html {
    scroll-padding-top: 20px;
  }

  .site-header {
    position: relative;
  }

  .header-inner {
    min-height: 0;
    flex-direction: column;
    align-items: stretch;
    gap: 15px;
    padding-block: 15px;
  }

  .site-logo {
    justify-content: center;
  }

  .site-logo img {
    max-height: 46px;
  }

  .site-nav {
    justify-content: center;
    flex-wrap: wrap;
    gap: 10px 19px;
  }

  .site-nav a:not(.btn) {
