  }

  .section {
    padding-block: 75px;
  }

  .hero {
    grid-template-columns: 1fr;
  }

  .hero-content {
    padding: 75px 6% 55px;
  }

  .hero h1 {
    font-size: clamp(2.7rem, 11vw, 4.4rem);
  }

  .hero-image {
    min-height: 340px;
  }

  .hero-image img {
    position: absolute;
    inset: 0;
  }

  .hero-trust {
    margin-top: 30px;
  }

  .services-layout,
  .about-layout,
  .roof-layout,
  .contact-layout {
    grid-template-columns: 1fr;
    gap: 38px;
  }

  .services-intro {
    position: static;
  }

  .about-image {
    min-height: 350px;
  }

  .roof-image {
    min-height: 350px;
  }

  .process-intro {
    grid-template-columns: 1fr;
    gap: 10px;
    margin-bottom: 35px;
  }

  .process-steps {
