/* ==================================================
   RESPONSIVE: SMALL PHONES
================================================== */
@media (max-width: 460px) {
  body {
    font-size: 15px;
  }

  h2 {
    font-size: 2.25rem;
  }

  .hero-content {
    padding-top: 58px;
  }

  .hero-actions {
    width: 100%;
    align-items: stretch;
    flex-direction: column;
  }

  .hero-actions .btn {
    width: 100%;
  }

  .hero-image {
    min-height: 270px;
  }

  .about-facts {
    gap: 20px 12px;
  }

  .about-fact strong {
    font-size: 2rem;
  }

  .service-item {
    grid-template-columns: 42px 1fr;
    gap: 12px;
  }

  .project-card,
  .project-card:first-child {
    min-height: 260px;
  }

  .contact-form {
    grid-template-columns: 1fr;
  }

  .form-field.full-width,
  .contact-form .btn,
  .form-note {
    grid-column: 1;
  }

  .contact-form .btn {
    width: 100%;
  }

  .footer-nav {
    gap: 13px 20px;
  }
}

/* ==================================================
   KEYBOARD ACCESSIBILITY
================================================== */
a:focus-visible,
button:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible {
  outline: 3px solid #e3a185;
  outline-offset: 4px;
}

.site-nav a:focus-visible,
.footer-nav a:focus-visible {
  border-radius: 2px;
}

/* ==================================================
   REDUCED MOTION
================================================== */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  .btn:hover,
  .project-card:hover img {
    transform: none;
  }
}
